<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class checklistmodel extends CI_Model {    public function __construct()    {        parent::__construct();    }    function fnGetInfo($VarChecklist = '', $VarStatus = '', $VarId = '') {        $this->db->select('id,description,updatedby,status,datecreated,dateupdated');        $this->db->from(KN_MASTER_CHECKLIST);        if ($VarStatus <> '') {            $this->db->where_in('status', array($VarStatus));        } else {            $this->db->where_in('status', array(1, 2));        }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarChecklist <> '') {            $ArrWhere['description'] = $VarChecklist;        }        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheck($VarData = '', $VarId = '') {        $this->db->from(KN_MASTER_CHECKLIST);        $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarData <> '') {            $ArrWhere['description'] = $VarData;        }        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetInfo($ArrUpdateData['description'], 1);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_CHECKLIST, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This record already exists!!";            }        } else {            $ArrCheckExist = $this->fnCheck($ArrUpdateData['description'], $VarId);            /*echo '<pre>';            print_r($ArrCheckExist);            die('die');*/            if ($ArrCheckExist === 0) {                if ($this->db->update(KN_MASTER_CHECKLIST, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data!';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This record has already Exist!";            }        }        return $ArrResult;    }    function fnCount($VarDesc = '', $VarStatus = '', $VarAfilter = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $ArrWhere = array();        if ($VarDesc <> '') {            $ArrWhere[] = "c.description like '%" . $VarDesc . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "c.status=" . $VarStatus;        } else {            $ArrWhere[] = "c.status in(1,2)";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "c.description LIKE '" . $VarAfilter . "%'";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND c.companyid = '" . $ArrUserLoggedInfo['companyid'] . "'";        }        $VarSqlLab = "SELECT count(1) as trec  FROM " . KN_MASTER_CHECKLIST . " AS c INNER JOIN " . KN_USERS . " AS u ON c.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnList($VarDesc = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder, $VarAfilter = '') {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('c.description', 'status', 'u.contactname', 'c.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'c.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarDesc <> '') {            $ArrWhere[] = "c.description like '%" . $VarDesc . "%'";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "c.description LIKE '" . $VarAfilter . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "c.status=" . $VarStatus;        } else {            $ArrWhere[] = "c.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND c.companyid = '" . $ArrUserLoggedInfo['companyid'] . "' ";        }        $VarSqlLab = "SELECT c.id,c.description,u.contactname,c.datecreated,c.dateupdated,c.status FROM " . KN_MASTER_CHECKLIST . " AS c         LEFT JOIN " . KN_USERS . " AS u ON c.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder . " limit " . $VarLimitInfo;        $ObjResult = $this->db->query($VarSqlLab);        return $ObjResult;    }    function changeCheckListStatus($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_CHECKLIST, array('status' => $optvalue))) {            return true;        }        return false;    }}